```go
package main

import (
    "fmt"
    "sort"
)

func main() {
    results := make(chan int, 4)
    for n := 1; n <= 4; n++ {
        go func(value int) { results <- value * value }(n)
    }

    squares := make([]int, 0, 4)
    for range 4 {
        squares = append(squares, <-results)
    }
    sort.Ints(squares)
    fmt.Println(squares)
}
```
Work may finish in any order, so the example sorts before printing. Its deterministic output is `[1 4 9 16]`.

```go
package main

import (
    "fmt"
    "sync"
)

func main() {
    jobs := make(chan int)
    results := make(chan int, 4)
    var wg sync.WaitGroup

    for range 2 {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for n := range jobs {
                results <- n * 10
            }
        }()
    }
    go func() {
        for n := 1; n <= 4; n++ { jobs <- n }
        close(jobs)
        wg.Wait()
        close(results)
    }()

    total := 0
    for value := range results { total += value }
    fmt.Println(total)
}
```
Only two workers can process jobs at once, and the final total is always `100`.
